style.css:
@-moz-document regexp(".*") {
/* Set global background to deep pitch black */
    html, body {
        background-color: #000000 !important;
        background-image: none !important;
    }

    /* Force all text elements to your custom neon purple */
    h1, h2, h3, h4, h5, h6, p, span, a, li, td, div {
        color: #9D00FF !important;
        /* Optional: Adds a subtle neon glow effect to main headers */
        text-shadow: 0 0 5px rgba(157, 0, 255, 0.5) !important;
    }

    /* Keep input fields and code blocks dark but legible */
    input, textarea, select, pre, code {
        background-color: #121212 !important;
        color: #E024C3 !important; /* Secondary accent pink/purple for inputs */
        border: 1px solid #9D00FF !important;
    }

    /* Style links so they stand out slightly with a brighter orchid pink */
    a {
        color: #E024C3 !important;
        text-decoration: underline !important;
    }
    
    a:hover {
        color: #FFFFFF !important; /* Glow white on hover */
    }
}
